{"operation":"run_python","code":"import os

workspace = '.'
files = []
for root, dirs, filenames in os.walk(workspace):
    for filename in filenames:
        files.append(os.path.join(root, filename))

keywords = ['basil', 'carmine', 'chef', 'panic']
found_contexts = []

for f in files:
    try:
        with open(f, 'r', encoding='utf-8', errors='ignore') as file:
            content = file.read()
            if any(k.lower() in content.lower() for k in keywords):
                found_contexts.append((f, content[:500])) # Just first 500 chars
    except Exception as e:
        pass

print("Files with keywords:", len(found_contexts))
for f, context in found_contexts:
    print(f"--- {f} ---")
    print(context)"}

{"code":"import urllib.request
from bs4 import BeautifulSoup
import json

# Search for Mrs Doubtfire cast
url = "https://en.wikipedia.org/wiki/Mrs._Doubtfire"
req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
try:
    html = urllib.request.urlopen(req).read()
    soup = BeautifulSoup(html, 'html.parser')
    # Find the cast section or infobox
    info_box = soup.find('table', class_='infobox')
    if info_box:
        rows = info_box.find_all('tr')
        for row in rows:
            header = row.find(['th', 'td'])
            if header and 'Starring' in header.text:
                print(header.find_next_sibling('td').text)
except Exception as e:
    print(e)
